#!/usr/bin/env python3
"""Fail when Chinese interface text in the iOS / macOS sources is not localized (docs/ui-ux.md, "自动检查").

    python3 .github/scripts/apple_strings.py            # check apps/ios/Sources against Localizable.xcstrings
    python3 .github/scripts/apple_strings.py --self-test

Simplified Chinese is the source language: the Swift code writes Chinese, and SwiftUI / Foundation look that text up
in apps/ios/Sources/NetworkCoreApp/Resources/Localizable.xcstrings (one catalogue, built into the app, the Mac app,
the packet tunnel and the widget). A string with no entry, or one that never goes through a lookup, shows Simplified
Chinese to English and Traditional Chinese users. Nothing extracts keys at build time (the project is generated by
XcodeGen and the catalogue is kept by hand), so this check does it. Four rules:

  S1 missing        Chinese text with no entry in the catalogue. Interpolations match any format specifier
                    (`\\(count) 个请求` is the key "%lld 个请求"), so the entry must use the specifier the compiler
                    generates: %lld for Int, %llu for UInt64, %@ for String, %lf for Double.
  S2 untranslated   an entry (any entry, used or not) whose en or zh-Hant is missing or not "translated", or whose
                    translation has different format specifiers from the key.
  S3 not-looked-up  Chinese text that reaches the screen as a plain String: an argument of a parameter declared
                    String, a value returned from a function or property declared String, a String variable, or
                    Text(verbatim:). SwiftUI shows such a String as it is, entry or not. Make the parameter
                    LocalizedStringKey / LocalizedStringResource, or write String(localized: "...").
  S4 unknown        Chinese text in a place this check cannot follow (a closure's result, an untyped constant). Write
                    it where the lookup is visible: String(localized:), a LocalizedStringKey parameter or property.

Text that is not interface text (demonstration node names, text written into a generated plugin file, a pattern
matched against the terms document) is listed in DATA below, each with the reason; adding to it needs that reason.
The command-line tool's terminal output (docs/macos-cli.md) and the Siri / Shortcuts phrases (which belong in their
own AppShortcuts table) are outside this check.

Standard library only.
"""

from __future__ import annotations

import json
import re
import subprocess
import sys
from dataclasses import dataclass, field
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SOURCES = "apps/ios/Sources/"
CATALOGUE = "apps/ios/Sources/NetworkCoreApp/Resources/Localizable.xcstrings"
LANGUAGES = ("en", "zh-Hant")

# Terminal output of the `anixops` command-line tool and the app's answers to it (docs/macos-cli.md).
COMMAND_LINE = (
    "apps/ios/Sources/NetworkCoreCLI/",
    "apps/ios/Sources/NetworkCoreBridge/CommandLine.swift",
    "apps/ios/Sources/NetworkCoreMac/MacControlService.swift",
)

# Chinese text that is data, not interface text: (path, text the literal starts with, why).
DATA = (
    ("apps/ios/Sources/NetworkCoreAppHost/DashboardModel.swift", "香港 01", "demonstration node name (screenshots)"),
    ("apps/ios/Sources/NetworkCoreAppHost/DashboardModel.swift", "日本 01", "demonstration node name (screenshots)"),
    ("apps/ios/Sources/NetworkCoreAppHost/DashboardModel.swift", "美国 01", "demonstration node name (screenshots)"),
    ("apps/ios/Sources/NetworkCoreAppHost/DashboardModel.swift", "新加坡 01", "demonstration node name (screenshots)"),
    ("apps/ios/Sources/NetworkCoreAppHost/DashboardModel.swift", "{\"groups\"",
     "demonstration policy groups (screenshots)"),
    ("apps/ios/Sources/NetworkCoreAppHost/TunnelController.swift", "香港 0", "demonstration node name (screenshots)"),
    ("apps/ios/Sources/NetworkCoreAppHost/TunnelController.swift", "日本 01", "demonstration node name (screenshots)"),
    ("apps/ios/Sources/NetworkCoreAppHost/TunnelController.swift", "新加坡 01", "demonstration node name (screenshots)"),
    ("apps/ios/Sources/NetworkCoreAppHost/TunnelController.swift", "美国 01", "demonstration node name (screenshots)"),
    ("apps/ios/Sources/NetworkCoreAppHost/TunnelController.swift", "德国 01", "demonstration node name (screenshots)"),
    ("apps/ios/Sources/NetworkCoreAppHost/TunnelController.swift", "节点选择",
     "demonstration policy group name (screenshots)"),
    ("apps/ios/Sources/NetworkCoreBridge/DebugMappings.swift", "AnixOps 调试映射",
     "name inside the generated plugin file; existing installs find their plugin by it"),
    ("apps/ios/Sources/NetworkCoreBridge/DebugMappings.swift", "#!desc=", "header line of the generated plugin file"),
    ("apps/ios/Sources/NetworkCoreBridge/SubscriptionGroup.swift", "订阅·",
     "prefix of policy group names written into the engine configuration"),
    ("apps/ios/Sources/NetworkCoreBridge/TermsConsent.swift", "基准版本",
     "pattern matched against TERMS.md, which is Chinese"),
)

HAN = re.compile(r"[\u3400-\u4dbf\u4e00-\u9fff\u3000-\u303f\uff01-\uff5e]")
SPECIFIER = r"%(?:\d+\$)?(?:lld|llu|ld|lu|lf|d|u|@|f|\.\d+f|\.\d+lf)"
SPECIFIER_RE = re.compile(r"%%|" + SPECIFIER)

# SwiftUI, Foundation and App Intents initializers and modifiers whose argument is looked up in the catalogue:
# callee -> argument labels that are looked up ("_" is the first unlabelled argument).
LOOKUP_CALLS: dict[str, tuple[str, ...]] = {
    "Text": ("_",), "Button": ("_",), "Label": ("_",), "Toggle": ("_",), "Picker": ("_",), "TextField": ("_",),
    "SecureField": ("_",), "Section": ("_",), "LabeledContent": ("_",), "Link": ("_",), "Menu": ("_",),
    "NavigationLink": ("_",), "TableColumn": ("_",), "CommandMenu": ("_",), "Window": ("_",),
    "WindowGroup": ("_",), "Stepper": ("_",), "DisclosureGroup": ("_",), "GroupBox": ("_",),
    "ContentUnavailableView": ("_",), "ProgressView": ("_",), "Settings": ("_",), "MenuBarExtra": ("_",),
    "navigationTitle": ("_",), "accessibilityLabel": ("_",), "accessibilityHint": ("_",),
    "accessibilityValue": ("_",), "help": ("_",), "confirmationDialog": ("_",), "alert": ("_",), "badge": ("_",),
    "searchable": ("prompt",), "accessibilityAction": ("named",),
    "LocalizedStringKey": ("_",), "LocalizedStringResource": ("_",), "IntentDescription": ("_",),
    "configurationDisplayName": ("_",), "description": ("_",), "displayName": ("_",),
    "DisplayRepresentation": ("title", "subtitle"), "TypeDisplayRepresentation": ("name",),
    "Parameter": ("title", "description"), "AppShortcut": ("shortTitle",),
    "value": ("_",),  # Charts: .value("时间", date)
}
LOOKUP_TYPES = ("LocalizedStringKey", "LocalizedStringResource", "LocalizationValue", "TypeDisplayRepresentation",
                "DisplayRepresentation", "IntentDescription")


@dataclass(frozen=True)
class Literal:
    start: int
    end: int
    parts: tuple[tuple[str, str], ...]  # ("lit", text) / ("expr", interpolated expression)

    @property
    def text(self) -> str:
        return "".join(v for k, v in self.parts if k == "lit")

    @property
    def key(self) -> str:
        """The catalogue key, with a NUL where an interpolation's specifier goes. Only a literal with
        interpolations is a format string, so only then is a "%" in its text written "%%"."""
        if all(k == "lit" for k, _ in self.parts):
            return self.text
        return "".join(v.replace("%", "%%") if k == "lit" else "\x00" for k, v in self.parts)


# ---------------------------------------------------------------------------------------------------------------
# Lexing: string literals (with interpolations) and a copy of the code with comments and literals blanked out.


def lex(text: str) -> tuple[list[Literal], str]:
    literals: list[Literal] = []
    code = list(text)
    n = len(text)

    def blank(a: int, b: int) -> None:
        for k in range(a, b):
            if code[k] != "\n":
                code[k] = " "

    def read_string(i: int) -> tuple[int, list[tuple[str, str]]]:
        hashes = 0
        while text[i] == "#":
            hashes += 1
            i += 1
        multi = text.startswith('"""', i)
        i += 3 if multi else 1
        close = ('"""' if multi else '"') + "#" * hashes
        escape = "\\" + "#" * hashes
        parts: list[tuple[str, str]] = []
        buf: list[str] = []
        while i < n:
            if text.startswith(close, i):
                i += len(close)
                break
            if text.startswith(escape, i):
                j = i + len(escape)
                c = text[j]
                if c == "(":
                    depth, k = 1, j + 1
                    while k < n and depth:
                        ch = text[k]
                        if ch == '"' or (ch == "#" and re.match(r'#+"', text[k:k + 8])):
                            k, _ = read_string(k)
                            continue
                        depth += {"(": 1, ")": -1}.get(ch, 0)
                        k += 1
                    if buf:
                        parts.append(("lit", "".join(buf)))
                        buf = []
                    parts.append(("expr", text[j + 1:k - 1]))
                    i = k
                    continue
                simple = {"n": "\n", "t": "\t", '"': '"', "\\": "\\", "'": "'", "0": "\0", "r": "\r"}
                if c in simple:
                    buf.append(simple[c])
                    i = j + 1
                    continue
                unicode = re.match(r"u\{([0-9a-fA-F]+)\}", text[j:j + 12])
                if unicode:
                    buf.append(chr(int(unicode.group(1), 16)))
                    i = j + len(unicode.group(0))
                    continue
                if multi and c == "\n":  # line continuation
                    i = j + 1
                    continue
                buf.append(c)
                i = j + 1
                continue
            buf.append(text[i])
            i += 1
        if buf:
            parts.append(("lit", "".join(buf)))
        if multi:
            parts = dedent(parts)
        return i, parts

    i = 0
    while i < n:
        if text.startswith("//", i):
            j = text.find("\n", i)
            j = n if j < 0 else j
            blank(i, j)
            i = j
        elif text.startswith("/*", i):
            depth, j = 1, i + 2
            while j < n and depth:
                if text.startswith("/*", j):
                    depth, j = depth + 1, j + 2
                elif text.startswith("*/", j):
                    depth, j = depth - 1, j + 2
                else:
                    j += 1
            blank(i, j)
            i = j
        elif text[i] == '"' or (text[i] == "#" and re.match(r'#+"', text[i:i + 8])):
            end, parts = read_string(i)
            literals.append(Literal(i, end, tuple(parts)))
            blank(i, end)
            code[i] = '"'
            i = end
        else:
            i += 1
    return literals, "".join(code)


def dedent(parts: list[tuple[str, str]]) -> list[tuple[str, str]]:
    """A multi-line literal: drop the first and last line break and the closing delimiter's indentation."""
    flat = "".join(v if k == "lit" else "\x01" for k, v in parts)
    lines = flat.split("\n")
    indent = re.match(r"[ \t]*", lines[-1]).group(0) if lines[-1].strip() == "" else ""
    body = lines[1:-1] if lines[-1].strip() == "" else lines[1:]
    flat = "\n".join(line[len(indent):] if line.startswith(indent) else line for line in body)
    exprs = iter(v for k, v in parts if k == "expr")
    out: list[tuple[str, str]] = []
    for index, chunk in enumerate(flat.split("\x01")):
        if index:
            out.append(("expr", next(exprs)))
        if chunk:
            out.append(("lit", chunk))
    return out


# ---------------------------------------------------------------------------------------------------------------
# Declarations: parameter and result types of the functions, initializers and properties in the sources.

OPEN = {"(": ")", "[": "]", "{": "}"}
CLOSE = {v: k for k, v in OPEN.items()}


def matching(code: str, open_index: int) -> int:
    depth = 0
    for i in range(open_index, len(code)):
        c = code[i]
        if c in OPEN:
            depth += 1
        elif c in CLOSE:
            depth -= 1
            if depth == 0:
                return i
    return len(code)


def split_top(text: str, sep: str = ",") -> list[str]:
    out, depth, start = [], 0, 0
    for i, c in enumerate(text):
        if c in OPEN or c == "<":
            depth += 1
        elif c in CLOSE or (c == ">" and text[i - 1] != "-"):
            depth -= 1
        elif c == sep and depth == 0:
            out.append(text[start:i])
            start = i + 1
    out.append(text[start:])
    return out


@dataclass
class Param:
    label: str
    type: str


@dataclass
class Index:
    funcs: dict[str, list[list[Param]]] = field(default_factory=dict)  # name -> parameter lists
    inits: dict[str, list[list[Param]]] = field(default_factory=dict)  # type name -> parameter lists
    vars: dict[str, list[str]] = field(default_factory=dict)  # property / variable name -> types

    def merged(self, other: "Index") -> "Index":
        out = Index()
        for mine, theirs, merged in ((self.funcs, other.funcs, out.funcs), (self.inits, other.inits, out.inits),
                                     (self.vars, other.vars, out.vars)):
            for source in (mine, theirs):
                for k, v in source.items():
                    merged.setdefault(k, []).extend(v)
        return out


def parse_params(text: str) -> list[Param]:
    params = []
    for raw in split_top(text):
        raw = re.sub(r"@\w+(\([^)]*\))?\s*", "", raw).strip()
        if ":" not in raw:
            continue
        names, _, rest = raw.partition(":")
        type_ = split_top(rest, "=")[0].strip()
        words = names.split()
        if not words:
            continue
        params.append(Param(words[0], type_))
    return params


def owner_at(code: str, pos: int) -> str:
    """The type whose body contains pos (struct / class / enum / actor / extension)."""
    for m in reversed(list(re.finditer(r"\b(?:struct|class|enum|actor|extension)\s+(\w+)[^{;]*\{", code[:pos]))):
        if matching(code, m.end() - 1) > pos:
            return m.group(1)
    return ""


def index_file(code: str) -> Index:
    index = Index()
    for m in re.finditer(r"\bfunc\s+(\w+)\s*(?:<[^>(]*>)?\s*\(", code):
        close = matching(code, m.end() - 1)
        index.funcs.setdefault(m.group(1), []).append(parse_params(code[m.end():close]))
    for m in re.finditer(r"\binit[?!]?\s*(?:<[^>(]*>)?\s*\(", code):
        close = matching(code, m.end() - 1)
        index.inits.setdefault(owner_at(code, m.start()), []).append(parse_params(code[m.end():close]))
    for m in re.finditer(r"\bstruct\s+(\w+)[^{;]*\{", code):
        close = matching(code, m.end() - 1)
        body, depth, members = code[m.end():close], 0, []
        for line in body.split("\n"):
            if depth == 0:
                d = re.match(r"\s*(?:@\w+(?:\([^)]*\))?\s+)*(?:(?:private|fileprivate|public|internal)\s+)?"
                             r"(?:let|var)\s+(\w+)\s*:\s*([^={]+?)\s*(=.*)?$", line)
                if d and "{" not in line:
                    members.append(Param(d.group(1), d.group(2).strip()))
            depth += line.count("{") - line.count("}")
        index.inits.setdefault(m.group(1), []).append(members)
    for m in re.finditer(r"\b(?:let|var)\s+(\w+)\s*:\s*([\w.<>\[\]?! ]+?)\s*(?:=|\{|\n)", code):
        index.vars.setdefault(m.group(1), []).append(m.group(2).strip())
    return index


def kind_of(types: list[str]) -> str:
    """lookup / string / unknown for a set of declared types."""
    if not types:
        return "unknown"
    kinds = set()
    for t in types:
        t = t.replace("?", "").replace("!", "").strip().strip("[]").strip()
        if any(t.endswith(x) for x in LOOKUP_TYPES):
            kinds.add("lookup")
        elif t in ("String", "Substring", "any StringProtocol") or t.startswith("String "):
            kinds.add("string")
        else:
            kinds.add("unknown")
    return kinds.pop() if len(kinds) == 1 else "unknown"


# ---------------------------------------------------------------------------------------------------------------
# Context: where a literal goes.


def enclosing(code: str, pos: int) -> tuple[str | None, int]:
    depth = {"(": 0, "[": 0, "{": 0}
    for i in range(pos - 1, -1, -1):
        c = code[i]
        if c in CLOSE:
            depth[CLOSE[c]] += 1
        elif c in OPEN:
            if depth[c] == 0:
                return c, i
            depth[c] -= 1
    return None, -1


def argument(code: str, open_index: int, pos: int) -> tuple[str, int, str]:
    """(label, argument index, text of the argument before the literal)."""
    depth, start, index = 0, open_index + 1, 0
    for i in range(open_index + 1, pos):
        c = code[i]
        if c in OPEN:
            depth += 1
        elif c in CLOSE:
            depth -= 1
        elif c == "," and depth == 0:
            start, index = i + 1, index + 1
    segment = code[start:pos]
    m = re.match(r"\s*(\w+)\s*:(?!:)", segment)
    return (m.group(1) if m else "_"), index, segment


def resolve_call(name: str, label: str, position: int, indexes: tuple[Index, ...]) -> str:
    """The declared type of the parameter the argument goes to; the file's own declarations come first, so a
    private helper is not confused with a function of the same name elsewhere."""
    for index in indexes:
        candidates = index.inits.get(name, []) if name[:1].isupper() else index.funcs.get(name, [])
        if name == "init":
            candidates = [p for lists in index.inits.values() for p in lists]
        types = []
        for params in candidates:
            if label != "_":
                types += [p.type for p in params if p.label == label]
            elif position < len(params) and params[position].label == "_":
                types.append(params[position].type)
        if types:
            return kind_of(types)
    return "unknown"


def result_type(code: str, pos: int) -> str:
    """The declared type of the function or property whose body returns the value at pos."""
    while True:
        c, brace = enclosing(code, pos)
        if c is None:
            return ""
        if c != "{":
            pos = brace
            continue
        boundary = max(code.rfind(ch, 0, brace) for ch in "{};")
        header = code[boundary + 1:brace].strip()
        header = re.sub(r"\s+", " ", header)
        if re.search(r"\bfunc\b", header):
            m = re.search(r".*->\s*([^{]+?)\s*(?:where\b.*)?$", header)
            return m.group(1) if m else ""
        m = re.search(r"\b(?:var|let)\s+\w+\s*:\s*(.+?)$", header)
        if m:
            return m.group(1)
        if re.match(r"^(?:#\w+.*?)?\s*(?:switch|if|else|guard|case|default|for|while|do|catch|get|"
                    r"(?:case\s.*|default)\s*:)\b", header) or header in ("", "else", "get", "do"):
            pos = brace
            continue
        if re.search(r"\b(?:switch|if|guard|else)\b", header):
            pos = brace
            continue
        return ""


def classify(code: str, lit: Literal, indexes: tuple[Index, ...], file_vars: dict[str, list[str]]) -> tuple[str, str]:
    """("lookup" | "string" | "unknown" | "skip", where)."""
    pos = lit.start
    while True:
        c, opener = enclosing(code, pos)
        if c == "(":
            label, position, _ = argument(code, opener, pos)
            m = re.search(r"([\w.]+)\s*$", code[:opener])
            callee = (m.group(1) if m else "").split(".")[-1]
            where = f"{callee}({label}:)" if label != "_" else f"{callee}(_)"
            if callee == "String" and label == "localized":
                return "lookup", where
            if label == "verbatim":
                return "string", "Text(verbatim:)"
            if callee in LOOKUP_CALLS:
                looked = LOOKUP_CALLS[callee]
                if (label in looked and (label != "_" or position == 0)):
                    return "lookup", where
            if callee == "":
                pos = opener  # a parenthesised expression or a tuple: where does it go?
                continue
            if callee == "Summary":
                return "skip", "App Intents parameter summary"
            if callee == "joined":
                return "string", where  # a separator inside shown text; use .formatted(.list(type:))
            if callee in ("split", "components", "range", "contains", "hasPrefix", "hasSuffix", "firstRange",
                          "replacingOccurrences", "print", "log", "debug", "info", "notice", "fault", "warning"):
                return "skip", where  # matched against data or written to a log, never shown
            return resolve_call(callee, label, position, indexes), where
        if c == "[":
            before = code[:opener].rstrip()
            if before.endswith("phrases:"):
                return "skip", "AppShortcut phrases"
            pos = opener
            continue
        # A statement: a return value or an assignment.
        start = max(code.rfind("\n", 0, pos), code.rfind("{", 0, pos), code.rfind(";", 0, pos)) + 1
        statement = code[start:pos].strip()
        assign = re.search(r"(?:^|[^=!<>])=(?!=)", statement)
        if assign:
            target = statement[:assign.start() + 1].strip()
            typed = re.search(r"\b(?:let|var)\s+\w+\s*:\s*(.+?)\s*=?$", target + "=")
            if typed:
                return kind_of([typed.group(1).rstrip("= ").strip()]), "declaration"
            name = re.search(r"(\w+)\s*$", target)
            if name and name.group(1) in file_vars:
                return kind_of(file_vars[name.group(1)]), f"{name.group(1)} ="
            return "unknown", "assignment"
        declared = result_type(code, pos)
        return kind_of([declared]) if declared else "unknown", "result"


# ---------------------------------------------------------------------------------------------------------------
# Catalogue


def placeholders(text: str) -> list[str]:
    out = []
    for m in SPECIFIER_RE.finditer(text):
        if m.group(0) == "%%":
            continue
        out.append(re.sub(r"\d+\$", "", m.group(0)))
    return sorted(out)


def catalogue_findings(strings: dict) -> list[str]:
    findings = []
    for key, entry in strings.items():
        localizations = entry.get("localizations", {})
        for language in LANGUAGES:
            unit = localizations.get(language, {}).get("stringUnit")
            if not unit or unit.get("state") != "translated" or not unit.get("value"):
                findings.append(f"{CATALOGUE}: S2 {language} translation missing or not translated\n    {key!r}")
                continue
            if placeholders(unit["value"]) != placeholders(key):
                findings.append(f"{CATALOGUE}: S2 {language} translation has other format specifiers than the key\n"
                                f"    {key!r} -> {unit['value']!r}")
    return findings


def key_pattern(key: str) -> re.Pattern[str]:
    return re.compile("^" + SPECIFIER.join(re.escape(part) for part in key.split("\x00")) + "$")


def in_catalogue(key: str, keys: set[str], with_specifiers: list[str]) -> bool:
    if "\x00" not in key:
        return key in keys
    pattern = key_pattern(key)
    return any(pattern.match(k) for k in with_specifiers)


def is_data(path: str, lit: Literal) -> bool:
    return any(path == p and lit.text.startswith(prefix) for p, prefix, _ in DATA)


def check_source(path: str, text: str, index: Index, keys: set[str], with_specifiers: list[str]) -> list[str]:
    literals, code = lex(text)
    file_index = index_file(code)
    findings = []
    for lit in literals:
        if not HAN.search(lit.text) or is_data(path, lit):
            continue
        line = text.count("\n", 0, lit.start) + 1
        shown = lit.text.replace("\n", "\\n")[:120]
        kind, where = classify(code, lit, (file_index, index), file_index.vars)
        if kind == "skip":
            continue
        if kind == "string":
            findings.append(f"{path}:{line}: S3 shown as a plain String ({where}), never looked up\n    {shown}")
        elif kind == "unknown":
            findings.append(f"{path}:{line}: S4 cannot tell whether this is looked up ({where})\n    {shown}")
        if not in_catalogue(lit.key, keys, with_specifiers):
            findings.append(f"{path}:{line}: S1 no entry in Localizable.xcstrings\n    {shown}")
    return findings


def tracked(root: Path) -> list[str]:
    out = subprocess.run(["git", "-C", str(root), "ls-files", "-z"], check=True, capture_output=True).stdout
    return [p for p in out.decode("utf-8").split("\0") if p]


def sources(root: Path) -> list[str]:
    return [p for p in tracked(root) if p.startswith(SOURCES) and p.endswith(".swift")
            and not p.startswith(COMMAND_LINE)]


def run(root: Path) -> int:
    strings = json.loads((root / CATALOGUE).read_text(encoding="utf-8"))["strings"]
    keys = set(strings)
    with_specifiers = [k for k in keys if "%" in k]
    files = sources(root)
    index = Index()
    texts = {}
    for path in files:
        texts[path] = (root / path).read_text(encoding="utf-8")
        index = index.merged(index_file(lex(texts[path])[1]))
    findings = catalogue_findings(strings)
    for path in files:
        findings.extend(check_source(path, texts[path], index, keys, with_specifiers))
    for finding in findings:
        print(finding)
    if findings:
        print(f"\n{len(findings)} finding(s). Rules and fixes: docs/ui-ux.md, section 自动检查.", file=sys.stderr)
        return 1
    print(f"apple_strings: {len(files)} files, {len(strings)} catalogue entries, no findings")
    return 0


def self_test() -> int:
    keys = {"继续", "%lld 个请求", "生成根证书", "代理模式：%@"}
    with_specifiers = [k for k in keys if "%" in k]
    helpers = """
    private func step(_ number: Int, _ title: String, done: Bool) -> some View { Text(title) }
    private func item(_ title: LocalizedStringKey, _ value: String) -> some View { Text(title) }
    struct Card: View {
        let title: LocalizedStringKey
        var body: some View { Text(title) }
    }
    """
    cases = [
        ('Text("继续")', []),
        ('Text("没有的键")', ["S1"]),
        ('Text("\\(count) 个请求")', []),
        ('let s = String(localized: "\\(rows.count) 个请求")', []),
        ('Text(verbatim: "继续")', ["S3"]),
        ('step(1, "生成根证书", done: true)', ["S3"]),
        ('item("继续", value)', []),
        ('Card(title: "继续")', []),
        ('Text(flag ? "继续" : "没有的键")', ["S1"]),
        ('var title: LocalizedStringKey {\n switch self {\n case .a:\n return "继续"\n }\n}', []),
        ('var title: String {\n switch self {\n case .a:\n return "继续"\n }\n}', ["S3"]),
        ('func label() -> LocalizedStringKey { flag ? "继续" : "生成根证书" }', []),
        ('@State private var error: String?\nfunc f() { error = "继续" }', ["S3"]),
        ('@State private var error: String?\nfunc f() { error = String(localized: "继续") }', []),
        ('let title = String(localized: "代理模式：\\(name)")', []),
        ('let summary = "\\(prefix)：\\(name)"', ["S4", "S1"]),
        ('// Text("没有的键") in a comment', []),
        ('let names = [", ".joined(separator: "、")]', ["S3", "S1"]),
        ('AppShortcut(intent: X(), phrases: ["用 \\(.applicationName) 连接"], shortTitle: "继续")', []),
        ('LabeledContent("继续", value: "没有的键")', ["S4", "S1"]),
    ]
    failed = 0
    for source, expected in cases:
        text = helpers + "\n" + source
        literals, code = lex(text)
        index = index_file(code)
        got = [f.split(": ", 2)[1].split(" ")[0] for f in check_source("a.swift", text, index, keys, with_specifiers)]
        if sorted(got) != sorted(expected):
            failed += 1
            print(f"self-test: {source!r} gave {got}, expected {expected}")
    strings = {
        "继续": {"localizations": {"en": {"stringUnit": {"state": "translated", "value": "Continue"}},
                                   "zh-Hant": {"stringUnit": {"state": "translated", "value": "繼續"}}}},
        "%lld 个请求": {"localizations": {"en": {"stringUnit": {"state": "translated", "value": "%lld requests"}},
                                       "zh-Hant": {"stringUnit": {"state": "new", "value": "%lld 個請求"}}}},
        "%@ 和 %lld": {"localizations": {"en": {"stringUnit": {"state": "translated", "value": "%2$lld and %1$@"}},
                                        "zh-Hant": {"stringUnit": {"state": "translated", "value": "%@ 和 %@"}}}},
    }
    catalogue = catalogue_findings(strings)
    if len(catalogue) != 2:
        failed += 1
        print(f"self-test: catalogue findings {catalogue}, expected 2 (zh-Hant state, zh-Hant specifiers)")
    total = len(cases) + 1
    print(f"apple_strings self-test: {total - failed}/{total} passed")
    return 1 if failed else 0


if __name__ == "__main__":
    if "--self-test" in sys.argv[1:]:
        sys.exit(self_test())
    sys.exit(run(ROOT))
